#Requires -Version 7.0
# Read-only on PAYTON-LEGION2: summarizes every TRX of run unit-green-win-diag-20261019T1435
# (same parsing as the local Get-TrxSummary.ps1: document namespace manager, Counters, non-passed results).
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = 'F:/GitHub/McpServer/.worktrees/unit-green-baseline-20261019/TestResults/unit-green-win-diag-20261019T1435'
$messageChars = 500
"Now: $((Get-Date).ToString('s')) root=$root"
$totals = [ordered]@{ total = 0; executed = 0; passed = 0; failed = 0; notExecuted = 0 }
foreach ($file in Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.trx' | Sort-Object FullName) {
    "FILE $($file.FullName.Substring($root.Length)) bytes=$($file.Length) written=$($file.LastWriteTime.ToString('s'))"
    if ($file.Length -eq 0) { continue }
    [xml]$trx = Get-Content -LiteralPath $file.FullName -Raw
    $ns = [System.Xml.XmlNamespaceManager]::new($trx.NameTable)
    $ns.AddNamespace('t', $trx.DocumentElement.NamespaceURI)
    $summary = $trx.SelectSingleNode('//t:ResultSummary', $ns)
    $counters = $trx.SelectSingleNode('//t:ResultSummary/t:Counters', $ns)
    if ($null -eq $counters) { '  no Counters element'; continue }
    $c = [ordered]@{
        total       = [int]$counters.GetAttribute('total')
        executed    = [int]$counters.GetAttribute('executed')
        passed      = [int]$counters.GetAttribute('passed')
        failed      = [int]$counters.GetAttribute('failed')
        notExecuted = [int]$counters.GetAttribute('notExecuted')
    }
    foreach ($key in @($c.Keys)) { $totals[$key] += $c[$key] }
    ('  outcome={0} total={1} executed={2} passed={3} failed={4} notExecuted={5}' -f $summary.GetAttribute('outcome'), $c.total, $c.executed, $c.passed, $c.failed, $c.notExecuted)
    foreach ($result in $trx.SelectNodes('//t:UnitTestResult[@outcome!="Passed"]', $ns)) {
        $message = $result.SelectSingleNode('t:Output/t:ErrorInfo/t:Message', $ns)
        $text = if ($null -ne $message) { $message.InnerText.Trim() } else { '' }
        if ($text.Length -gt $messageChars) { $text = $text.Substring(0, $messageChars) + '...' }
        ('  {0}: {1}' -f $result.GetAttribute('outcome'), $result.GetAttribute('testName'))
        if ($text) { ('    {0}' -f ($text -replace "`r?`n", ' | ')) }
    }
}
('TOTAL total={0} executed={1} passed={2} failed={3} notExecuted={4}' -f $totals.total, $totals.executed, $totals.passed, $totals.failed, $totals.notExecuted)

