#Requires -Version 7.0
# Read-only on PAYTON-LEGION2 (as lab-wsman): reads FR, TR and TEST-MCP-PATHNORM-001 and
# TR-MCP-QUALITY-001 from the F:\GitHub\McpServer requirements store through the installed MCP
# plugin wrapper (lib/repl-invoke.ps1, getFr/getTr/getTest, listMappings), and prints each result
# as one compressed JSON line. Plugin cache, failsafe and temp files go to a folder inside this
# effort's own baseline worktree, so nothing is written into kingd's main tree; the folder is
# removed at the end.
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$plugin = 'C:/Users/kingd/.claude/plugins/cache/mcpserver-local/mcpserver/1.119.0'
$workspace = 'F:/GitHub/McpServer'
$scratch = 'F:/GitHub/McpServer/.worktrees/unit-green-baseline-20261019/.wsman-plugin'
"Now: $((Get-Date).ToString('s')) plugin=$plugin"
foreach ($sub in 'cache', 'failsafe', 'tmp') { New-Item -ItemType Directory -Force -Path (Join-Path $scratch $sub) | Out-Null }
$env:MCP_CACHE_DIR_OVERRIDE = Join-Path $scratch 'cache'
$env:MCPSERVER_FAILSAFE_DIR = Join-Path $scratch 'failsafe'
$env:TEMP = Join-Path $scratch 'tmp'
$env:TMP = $env:TEMP
$env:CLAUDE_PLUGIN_ROOT = $plugin
$env:PLUGIN_AGENT_NAME = 'Claude'
$env:MCP_PLUGIN_HOST = 'claude-code'
$pwshExe = Join-Path $PSHOME 'pwsh.exe'
. (Join-Path $plugin 'lib/yaml-object-mutation.ps1')
Import-McpYamlSerializer

function Invoke-LegionPlugin {
    param([Parameter(Mandatory)][string]$Method, [System.Collections.IDictionary]$Params = [ordered]@{})
    $yaml = ConvertTo-Yaml -Data $Params -Options WithIndentedSequences
    Push-Location -LiteralPath $workspace
    try {
        $raw = & $pwshExe -NoProfile -NonInteractive -File (Join-Path $plugin 'lib/repl-invoke.ps1') -Method $Method -ParamsYaml $yaml 2>&1
        $exit = $LASTEXITCODE
    }
    finally {
        Pop-Location
    }
    $text = (@($raw) | ForEach-Object { [string]$_ }) -join "`n"
    $parsed = $null
    try { $parsed = ConvertFrom-Yaml -Yaml $text } catch { $parsed = $null }
    [pscustomobject]@{ Exit = $exit; Raw = $text; Parsed = $parsed }
}

try {
    foreach ($pair in @(
            @('workflow.requirements.getFr', 'FR-MCP-PATHNORM-001'),
            @('workflow.requirements.getTr', 'TR-MCP-PATHNORM-001'),
            @('workflow.requirements.getTest', 'TEST-MCP-PATHNORM-001'),
            @('workflow.requirements.getTr', 'TR-MCP-QUALITY-001'))) {
        $r = Invoke-LegionPlugin -Method $pair[0] -Params ([ordered]@{ id = $pair[1] })
        $result = $null
        if ($r.Parsed -is [System.Collections.IDictionary] -and $r.Parsed.Contains('payload')) { $result = $r.Parsed['payload']['result'] }
        if ($null -eq $result) {
            "RECORD $($pair[1]) exit=$($r.Exit) UNPARSED"
            $r.Raw -split "`n" | Select-Object -First 30 | ForEach-Object { "  RAW $_" }
            continue
        }
        "RECORD $($pair[1]) exit=$($r.Exit) $($result | ConvertTo-Json -Depth 20 -Compress)"
    }
    $m = Invoke-LegionPlugin -Method 'workflow.requirements.listMappings'
    $items = @()
    if ($m.Parsed -is [System.Collections.IDictionary] -and $m.Parsed.Contains('payload')) { $items = @($m.Parsed['payload']['result']['items']) }
    "MAPPINGS exit=$($m.Exit) rows=$($items.Count)"
    foreach ($row in $items) {
        $json = $row | ConvertTo-Json -Depth 8 -Compress
        if ($json -match 'PATHNORM-001|TR-MCP-QUALITY-001') { "MAPPING $json" }
    }
}
finally {
    Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction SilentlyContinue
    "CLEANUP scratch removed=$(-not (Test-Path -LiteralPath $scratch))"
}

Input.old_string:
"RECORD $($pair[1]) exit=$($r.Exit) UNPARSED"
$r.Raw -split "`n" | Select-Object -First 30 | ForEach-Object { "  RAW $_" }
continue

