.DESCRIPTION
    Operator decision 2026-10-19 ("Copy from PAYTON-LEGION2"). The source is the receipt written by
    remote/Read-LegionRequirements.ps1 (one RECORD line of compressed JSON per record, read through the
    PAYTON-LEGION2 plugin wrapper). Field values are taken from that receipt, never retyped. Creates the
    three PATHNORM records with workflow.requirements.createBatch and the FR mapping with createMapping;
    replaces only the acceptanceCriteria of TR-MCP-QUALITY-001 with updateTr. Refuses if any PATHNORM
    id already exists here.
.PARAMETER SourceReceipt
    The Read-LegionRequirements receipt file.
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory)] [string] $SourceReceipt
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'CcPlugin.ps1')

function Test-Ok {
    param([Parameter(Mandatory)] $Result)
    return ($Result.ExitCode -eq 0 -and $Result.Raw -notmatch '(?im)^\s*type:\s*error')
}

function ConvertTo-CriteriaList {
    param($Criteria)
    $list = foreach ($c in @($Criteria)) {
        if ($null -eq $c) { continue }
        $item = [ordered]@{ id = [string]$c.id; text = [string]$c.text; isSatisfied = [bool]$c.isSatisfied }
        if ($c.PSObject.Properties['evidence'] -and $c.evidence) { $item.evidence = [string]$c.evidence }
        $item
    }
    return @($list)
}

function Get-CriteriaSignature {
    param($Criteria)
    return (@($Criteria | Where-Object { $null -ne $_ } | ForEach-Object {
                $evidence = if ($_ -is [System.Collections.IDictionary]) { $_['evidence'] } else { $_.evidence }
                $id = if ($_ -is [System.Collections.IDictionary]) { $_['id'] } else { $_.id }
                $text = if ($_ -is [System.Collections.IDictionary]) { $_['text'] } else { $_.text }
                $sat = if ($_ -is [System.Collections.IDictionary]) { $_['isSatisfied'] } else { $_.isSatisfied }
                '{0}|{1}|{2}|{3}' -f $id, $text, [bool]$sat, $evidence
            }) -join "`n")
}

Write-Output "Now: $((Get-Date).ToString('s')) source=$SourceReceipt"
$source = @{}
foreach ($line in Get-Content -LiteralPath $SourceReceipt) {
    if ($line -match '^RECORD (\S+) exit=0 (\{.*\})$') { $source[$Matches[1]] = $Matches[2] | ConvertFrom-Json }
}
foreach ($id in 'FR-MCP-PATHNORM-001', 'TR-MCP-PATHNORM-001', 'TEST-MCP-PATHNORM-001', 'TR-MCP-QUALITY-001') {
    if (-not $source.ContainsKey($id)) { throw "Source receipt has no exit=0 RECORD line for $id" }
}
Write-Output ('Source records: {0}' -f (($source.Keys | Sort-Object) -join ', '))

foreach ($pair in @(@('workflow.requirements.getFr', 'FR-MCP-PATHNORM-001'), @('workflow.requirements.getTr', 'TR-MCP-PATHNORM-001'), @('workflow.requirements.getTest', 'TEST-MCP-PATHNORM-001'))) {
    $g = Invoke-CcPlugin -Method $pair[0] -Params ([ordered]@{ id = $pair[1] })
    $exists = Test-Ok $g
    Write-Output ('{0} exists here before: {1}' -f $pair[1], $exists)
    if ($exists) { throw "Refusing: $($pair[1]) already exists in this store." }
}

$fr = $source['FR-MCP-PATHNORM-001']
$tr = $source['TR-MCP-PATHNORM-001']
$test = $source['TEST-MCP-PATHNORM-001']
$records = @(
    [ordered]@{ kind = 'fr'; id = $fr.id; title = $fr.title; description = $fr.description; priority = $fr.priority; area = $fr.area; acceptanceCriteria = (ConvertTo-CriteriaList $fr.acceptanceCriteria) }
    [ordered]@{ kind = 'tr'; id = $tr.id; title = $tr.title; description = $tr.description; priority = $tr.priority; area = $tr.area; subarea = $tr.subarea; notes = $tr.notes; acceptanceCriteria = (ConvertTo-CriteriaList $tr.acceptanceCriteria) }
    [ordered]@{ kind = 'test'; id = $test.id; title = $test.title; description = $test.description; priority = $test.priority; area = $test.area; notes = $test.notes; acceptanceCriteria = (ConvertTo-CriteriaList $test.acceptanceCriteria) }
)

if ($PSCmdlet.ShouldProcess('FR, TR, TEST-MCP-PATHNORM-001', 'workflow.requirements.createBatch')) {
    $c = Invoke-CcPlugin -Method 'workflow.requirements.createBatch' -Params ([ordered]@{ records = $records })
    Write-Output "createBatch exit=$($c.ExitCode) ok=$(Test-Ok $c)"
    if (-not (Test-Ok $c)) { Write-Output $c.Raw; exit 1 }
}
if ($PSCmdlet.ShouldProcess('FR-MCP-PATHNORM-001', 'createMapping TR-MCP-PATHNORM-001 and TEST-MCP-PATHNORM-001')) {
    $m = Invoke-CcPlugin -Method 'workflow.requirements.createMapping' -Params ([ordered]@{ frId = 'FR-MCP-PATHNORM-001'; trIds = @('TR-MCP-PATHNORM-001'); testIds = @('TEST-MCP-PATHNORM-001'); notes = 'Copied 2026-10-19 from the PAYTON-LEGION2 store (operator: "Copy from PAYTON-LEGION2"), where the same two mapping rows exist.' })
    Write-Output "createMapping exit=$($m.ExitCode) ok=$(Test-Ok $m)"
    if (-not (Test-Ok $m)) { Write-Output $m.Raw; exit 1 }
}
$qualityCriteria = ConvertTo-CriteriaList $source['TR-MCP-QUALITY-001'].acceptanceCriteria
if ($PSCmdlet.ShouldProcess("TR-MCP-QUALITY-001 ($($qualityCriteria.Count) criteria)", 'workflow.requirements.updateTr acceptanceCriteria')) {
    $u = Invoke-CcPlugin -Method 'workflow.requirements.updateTr' -Params ([ordered]@{ id = 'TR-MCP-QUALITY-001'; acceptanceCriteria = $qualityCriteria })
    Write-Output "updateTr TR-MCP-QUALITY-001 exit=$($u.ExitCode) ok=$(Test-Ok $u)"
    if (-not (Test-Ok $u)) { Write-Output $u.Raw; exit 1 }
}

if ($WhatIfPreference) {
    Write-Output ('WHATIF records: FR ACs={0}, TR ACs={1}, TEST ACs={2}, QUALITY ACs={3}' -f @($records[0].acceptanceCriteria).Count, @($records[1].acceptanceCriteria).Count, @($records[2].acceptanceCriteria).Count, $qualityCriteria.Count)
    return
}

$failures = 0
foreach ($pair in @(@('workflow.requirements.getFr', 'FR-MCP-PATHNORM-001'), @('workflow.requirements.getTr', 'TR-MCP-PATHNORM-001'), @('workflow.requirements.getTest', 'TEST-MCP-PATHNORM-001'), @('workflow.requirements.getTr', 'TR-MCP-QUALITY-001'))) {
    $g = Invoke-CcPlugin -Method $pair[0] -Params ([ordered]@{ id = $pair[1] })
    $result = Get-CcValue (Get-CcValue $g.Parsed 'payload') 'result'
    $src = $source[$pair[1]]
    $criteriaMatch = (Get-CriteriaSignature (Get-CcValue $result 'acceptanceCriteria')) -eq (Get-CriteriaSignature $src.acceptanceCriteria)
    $fieldsMatch = $true
    if ($pair[1] -ne 'TR-MCP-QUALITY-001') {
        foreach ($field in 'title', 'description', 'priority', 'area') {
            if ([string](Get-CcValue $result $field) -ne [string]$src.$field) { $fieldsMatch = $false; Write-Output "  MISMATCH $($pair[1]).$field" }
        }
    }
    if (-not ($criteriaMatch -and $fieldsMatch)) { $failures++ }
    Write-Output ('READBACK {0}: ok={1} ACs={2} criteriaMatchSource={3} fieldsMatchSource={4}' -f $pair[1], (Test-Ok $g), @(Get-CcValue $result 'acceptanceCriteria' | Where-Object { $null -ne $_ }).Count, $criteriaMatch, $fieldsMatch)
}
Write-Output "Done at $((Get-Date).ToString('s')) failures=$failures"
if ($failures -gt 0) { exit 1 }

