#Requires -Version 7.0
<#
.SYNOPSIS
    Replaces or adds exactly one acceptance criterion on a TR or TEST record through the plugin
    (getTr/getTest, then updateTr/updateTest with the full list), then reads the record back and
    proves that only the named criterion changed. Supports -WhatIf.
.PARAMETER DataFile
    PowerShell data file with keys Kind (tr or test), Id, Mode (Replace or Add), and Criterion
    (id, text, isSatisfied, optional evidence).
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory)] [string] $DataFile
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'CcPlugin.ps1')

function Test-Ok {
    param([Parameter(Mandatory)] $Result)
    return ($Result.ExitCode -eq 0 -and $Result.Raw -notmatch '(?im)^\s*type:\s*error')
}

function Get-Signature {
    param($Criterion)
    return ('{0}|{1}|{2}|{3}' -f (Get-CcValue $Criterion 'id'), (Get-CcValue $Criterion 'text'), [bool](Get-CcValue $Criterion 'isSatisfied'), (Get-CcValue $Criterion 'evidence'))
}

function Read-Criteria {
    param([string]$GetMethod, [string]$Id)
    $g = Invoke-CcPlugin -Method $GetMethod -Params ([ordered]@{ id = $Id })
    if (-not (Test-Ok $g)) { Write-Output $g.Raw; throw "Read of $Id failed" }
    $result = Get-CcValue (Get-CcValue $g.Parsed 'payload') 'result'
    return @(Get-CcValue $result 'acceptanceCriteria' | Where-Object { $null -ne $_ })
}

$data = Import-PowerShellDataFile -LiteralPath $DataFile
$kind = [string]$data.Kind
$id = [string]$data.Id
$mode = [string]$data.Mode
$new = $data.Criterion
if ($kind -notin 'tr', 'test') { throw "Kind must be tr or test, got '$kind'" }
if ($mode -notin 'Replace', 'Add') { throw "Mode must be Replace or Add, got '$mode'" }
$getMethod = if ($kind -eq 'tr') { 'workflow.requirements.getTr' } else { 'workflow.requirements.getTest' }
$updateMethod = if ($kind -eq 'tr') { 'workflow.requirements.updateTr' } else { 'workflow.requirements.updateTest' }

Write-Output "Now: $((Get-Date).ToString('s')) $id $mode criterion $($new.id)"
$before = Read-Criteria -GetMethod $getMethod -Id $id
$ids = @($before | ForEach-Object { [string](Get-CcValue $_ 'id') })
if ($mode -eq 'Replace' -and $ids -notcontains $new.id) { throw "Criterion $($new.id) not found on $id" }
if ($mode -eq 'Add' -and $ids -contains $new.id) { throw "Criterion $($new.id) already exists on $id" }

$newItem = [ordered]@{ id = [string]$new.id; text = [string]$new.text; isSatisfied = [bool]$new.isSatisfied }
if ($new.ContainsKey('evidence') -and $new.evidence) { $newItem.evidence = [string]$new.evidence }
$list = foreach ($c in $before) {
    if ($mode -eq 'Replace' -and [string](Get-CcValue $c 'id') -eq $new.id) { $newItem; continue }
    $item = [ordered]@{ id = [string](Get-CcValue $c 'id'); text = [string](Get-CcValue $c 'text'); isSatisfied = [bool](Get-CcValue $c 'isSatisfied') }
    $evidence = Get-CcValue $c 'evidence'
    if ($evidence) { $item.evidence = [string]$evidence }
    $item
}
$list = @($list)
if ($mode -eq 'Add') { $list += $newItem }
Write-Output ('Criteria before={0} after={1}' -f $before.Count, $list.Count)

if (-not $PSCmdlet.ShouldProcess("$id criterion $($new.id)", "$updateMethod ($mode)")) { return }
$u = Invoke-CcPlugin -Method $updateMethod -Params ([ordered]@{ id = $id; acceptanceCriteria = $list })
Write-Output "$updateMethod exit=$($u.ExitCode) ok=$(Test-Ok $u)"
if (-not (Test-Ok $u)) { Write-Output $u.Raw; exit 1 }

$after = Read-Criteria -GetMethod $getMethod -Id $id
$beforeById = @{}
foreach ($c in $before) { $beforeById[[string](Get-CcValue $c 'id')] = Get-Signature $c }
$changed = @()
foreach ($c in $after) {
    $cid = [string](Get-CcValue $c 'id')
    if (-not $beforeById.ContainsKey($cid) -or $beforeById[$cid] -ne (Get-Signature $c)) { $changed += $cid }
}
$expectedNew = Get-Signature $newItem
$target = @($after | Where-Object { [string](Get-CcValue $_ 'id') -eq $new.id })
$ok = ($changed.Count -eq 1 -and $changed[0] -eq $new.id -and $target.Count -eq 1 -and (Get-Signature $target[0]) -eq $expectedNew -and $after.Count -eq $list.Count)
Write-Output ('READBACK {0}: criteria={1} changed=[{2}] targetMatches={3} ok={4}' -f $id, $after.Count, ($changed -join ','), ($target.Count -eq 1 -and (Get-Signature $target[0]) -eq $expectedNew), $ok)
if (-not $ok) { exit 1 }

@{
    Kind      = 'tr'
    Id        = 'TR-MCP-QUALITY-001'
    Mode      = 'Replace'
    Criterion = @{
        id          = 'ac-21'
        text        = 'NU1901, NU1902, NU1903, and NU1904 are not approved. Vulnerable package advisories must be resolved by updating to the patched versions the advisories name, with a clean NuGet vulnerability audit on every lab host (LAB-OMARCHY and PAYTON-LEGION2), never by suppression, audit settings, or a build override.'
        isSatisfied = $false
        evidence    = 'REOPENED 2026-10-19 (operator: "Gotta use the recommended packages."): develop ace70daa pins System.Security.Cryptography.Xml 10.0.10 (Directory.Packages.props:91), which brings System.Security.Cryptography.Pkcs 10.0.10; on PAYTON-LEGION2 the restore of build/_build.csproj fails NU1902 (GHSA-2fmv-rv2c-59x7) and NU1903 (GHSA-846f-f764-76mx, GHSA-7hqp-7c5m-4vq6, GHSA-c399-9853-6jmj, GHSA-r955-8q5j-3h83), run unit-green-win-baseline-20261019T1433. All five advisories name 10.0.13. Text strengthened from "NU1901 and NU1903 are not approved. Vulnerable package advisories must be resolved by dependency updates and a clean vulnerability scan." Historical evidence retained: Directory.Packages.props transitive pins, Directory.Build.props suppression removal, and dotnet list McpServer.sln package --vulnerable --include-transitive.'
    }
}

@{
    Kind      = 'test'
    Id        = 'TEST-MCP-PATHNORM-001'
    Mode      = 'Add'
    Criterion = @{
        id          = 'unitgreen-native-host'
        text        = 'The native-boundary (ToNativePath) behavior for a non-Windows host is proven on every test host, Windows included, against a simulated host, without a host-conditional skip; the Windows-host cases keep running on a Windows host.'
        isSatisfied = $false
    }
}

