#Requires -Version 7.0
<#
.SYNOPSIS
    Opens (when absent) and completes several session-log turns by explicit requestId through the
    plugin, from a PowerShell data file, and reads each back. Used when the prompt hook filed each
    operator message to the failsafe queue. Supports -WhatIf.
.PARAMETER SessionId
    Session id.
.PARAMETER DataFile
    Data file with key Turns: a list of hashtables with RequestId, Title, QueryText, Interpretation,
    Response, and optional Tags, Actions, Decisions.
.PARAMETER Model
    Model id from the session metadata.
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory)] [string] $SessionId,
    [Parameter(Mandatory)] [string] $DataFile,
    [string] $Model = 'claude-opus-5-5'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'CcPlugin.ps1')

function Test-Ok {
    param([Parameter(Mandatory)] $Result)
    return ($Result.ExitCode -eq 0 -and $Result.Raw -notmatch '(?im)^\s*type:\s*error')
}

$data = Import-PowerShellDataFile -LiteralPath $DataFile
Write-Output "Now: $((Get-Date).ToString('s')) turns=$(@($data.Turns).Count)"
foreach ($t in @($data.Turns)) {
    $requestId = [string]$t.RequestId
    if ($requestId -notmatch '^req-\d{8}T\d{6}Z-[a-z0-9]+(?:-[a-z0-9]+)*$') { throw "Invalid requestId $requestId" }
    if (-not $PSCmdlet.ShouldProcess($requestId, 'begin (if absent), patch and complete')) { continue }
    $existing = Find-CcTurn -SessionId $SessionId -RequestId $requestId
    if (-not $existing.Found) {
        $b = Invoke-CcPlugin -Method 'client.SessionLog.BeginTurnAsync' -Params ([ordered]@{
                agent = 'ClaudeCode'; sessionId = $SessionId; requestId = $requestId
                queryTitle = [string]$t.Title; queryText = [string]$t.QueryText; model = $Model
                planFile = 'None'; todoId = 'None'
            })
        if (-not (Test-Ok $b)) { Write-Output "BEGIN FAILED $requestId"; Write-Output $b.Raw; exit 1 }
    }
    $turn = [ordered]@{ interpretation = [string]$t.Interpretation }
    if ($t.ContainsKey('Tags')) { $turn.tags = @($t.Tags) }
    if ($t.ContainsKey('Actions')) { $turn.actions = @($t.Actions) }
    if ($t.ContainsKey('Decisions')) { $turn.designDecisions = @($t.Decisions) }
    $p = Invoke-CcPlugin -Method 'client.SessionLog.PatchTurnAsync' -Params ([ordered]@{ agent = 'ClaudeCode'; sessionId = $SessionId; requestId = $requestId; turn = $turn })
    if (-not (Test-Ok $p)) { Write-Output "PATCH FAILED $requestId"; Write-Output $p.Raw; exit 1 }
    $c = Invoke-CcPlugin -Method 'client.SessionLog.CompleteTurnAsync' -Params ([ordered]@{ agent = 'ClaudeCode'; sessionId = $SessionId; requestId = $requestId; payload = [ordered]@{ response = [string]$t.Response; status = 'completed' } })
    if (-not (Test-Ok $c)) { Write-Output "COMPLETE FAILED $requestId"; Write-Output $c.Raw; exit 1 }
    $hit = Find-CcTurn -SessionId $SessionId -RequestId $requestId
    $status = if ($hit.Found) { Get-CcValue $hit.Turn 'status' } else { 'NOT FOUND' }
    Write-Output ('READBACK {0} status={1}' -f $requestId, $status)
}

