#Requires -Version 7.0
<#
.SYNOPSIS
    Read-only: inventories environment-dependent constructs in the unit test projects (the projects the
    Nuke Test target runs), per file and line, and marks files whose classes already carry
    Category=Integration. Heuristic: every hit still needs judging.
.PARAMETER Worktree
    Repository worktree.
.PARAMETER OutFile
    Optional file that receives the full listing.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Worktree,
    [string]$OutFile = ''
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$patterns = [ordered]@{
    'os-check'      = 'OperatingSystem\.Is\w+\(|RuntimeInformation\.(IsOSPlatform|OSDescription)|Environment\.OSVersion'
    'os-attribute'  = '\[SupportedOSPlatform|\[UnsupportedOSPlatform'
    'skip'          = 'Assert\.Skip(When|Unless)?\(|SkipException|Skip\s*='
    'platform-trait' = 'Trait\("Platform"'
    'process-host'  = 'SystemWorkspaceHostEnvironment\.Instance|WorkspacePathNormalizer\.Process\b'
    'native-tool'   = '"(pwsh|pwsh\.exe|powershell\.exe|cmd\.exe|/bin/sh|bash|mkfifo|sqllocaldb|initdb(\.exe)?|chmod|icacls)"'
    'separator'     = 'Path\.DirectorySeparatorChar|Path\.AltDirectorySeparatorChar'
}
$unitProjects = @(Get-ChildItem -LiteralPath (Join-Path $Worktree 'tests') -Directory |
        Where-Object { $_.Name -like '*.Tests' -and $_.Name -ne 'Build.Tests' -and $_.Name -notlike '*.IntegrationTests' } |
        Sort-Object Name)
$lines = [System.Collections.Generic.List[string]]::new()
$lines.Add("Now: $((Get-Date).ToString('s')) worktree=$Worktree projects=$($unitProjects.Name -join ', ')")
$totals = [ordered]@{}
foreach ($key in $patterns.Keys) { $totals[$key] = 0 }
$fileCount = 0
foreach ($project in $unitProjects) {
    foreach ($file in Get-ChildItem -LiteralPath $project.FullName -Recurse -File -Filter '*.cs' | Where-Object { $_.FullName -notmatch '[\\/](bin|obj)[\\/]' } | Sort-Object FullName) {
        $text = Get-Content -LiteralPath $file.FullName
        $integration = [bool](@($text | Where-Object { $_ -match 'Trait\("Category",\s*"Integration"\)' }).Count)
        $hits = @()
        for ($i = 0; $i -lt $text.Count; $i++) {
            foreach ($key in $patterns.Keys) {
                if ($text[$i] -match $patterns[$key]) { $hits += ('    {0,-14} {1}: {2}' -f $key, ($i + 1), $text[$i].Trim()); $totals[$key]++ }
            }
        }
        if ($hits.Count -eq 0) { continue }
        $fileCount++
        $relative = [System.IO.Path]::GetRelativePath($Worktree, $file.FullName)
        $lines.Add(('{0} hits={1}{2}' -f $relative, $hits.Count, $(if ($integration) { ' [has Category=Integration]' } else { '' })))
        foreach ($h in $hits) { $lines.Add($h) }
    }
}
$lines.Add(('TOTAL files={0} {1}' -f $fileCount, (($totals.Keys | ForEach-Object { "$_=$($totals[$_])" }) -join ' ')))
if ($OutFile) { Set-Content -LiteralPath $OutFile -Value $lines -Encoding utf8 }
$lines | Select-Object -Last 1
$lines | Where-Object { $_ -notmatch '^\s{4}' } | Select-Object -First 200

