Input.new_string:
if (-not (Test-Path -LiteralPath `$wt)) {
    git -C `$repo worktree add --detach `$wt '$Ref' 2>&1 | Out-File (Join-Path `$log 'worktree.txt')
}
else {
    # Earlier runs on this host rewrite generated tracked files (Nuke's schema, the memory-bench results);
    # restore those only, and stop when any other tracked file is modified.
    `$changed = @(git -C `$wt diff --name-only)
    `$generated = @(`$changed | Where-Object { `$_ -eq '.nuke/build.schema.json' -or `$_ -like 'docs/benchmarks/results/*' })
    `$other = @(`$changed | Where-Object { `$generated -notcontains `$_ })
    if (`$other.Count -gt 0) { "STOP: tracked changes outside the generated allowlist: `$(`$other -join ', ')"; return }
    foreach (`$path in `$generated) { "RESTORE generated `$path" }
    if (`$generated.Count -gt 0) { git -C `$wt restore --worktree -- @generated 2>&1 | Out-File (Join-Path `$log 'restore.txt') }
    git -C `$wt checkout --detach '$Ref' 2>&1 | Out-File (Join-Path `$log 'checkout.txt')
}
`$expected = (git -C `$repo rev-parse '$Ref').Trim()
`$actual = (git -C `$wt rev-parse HEAD).Trim()
if (`$expected -ne `$actual) {
    "STOP: HEAD `$actual is not $Ref (`$expected); checkout log follows"
    Get-Content -LiteralPath (Join-Path `$log 'checkout.txt') -ErrorAction SilentlyContinue | ForEach-Object { "  `$_" }
    return
}

