#Requires -Version 7.0
<#
.SYNOPSIS
    Removes the exact two-line silent platform return "if (!OperatingSystem.IsWindows())" + "return;"
    (and the blank line after it) from named test files, reporting each removal by line. Refuses when a
    file holds a different form. Supports -WhatIf.
.PARAMETER Paths
    Semicolon-separated absolute file paths.
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory)] [string] $Paths
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Write-Output "Now: $((Get-Date).ToString('s'))"
foreach ($path in @($Paths -split ';' | Where-Object { $_ })) {
    $text = [System.IO.File]::ReadAllText($path)
    $newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
    $lines = [System.Collections.Generic.List[string]]::new([string[]]($text -split [regex]::Escape($newline)))
    $removed = 0
    for ($i = $lines.Count - 2; $i -ge 0; $i--) {
        if ($lines[$i].Trim() -eq 'if (!OperatingSystem.IsWindows())' -and $lines[$i + 1].Trim() -eq 'return;') {
            $count = if ($i + 2 -lt $lines.Count -and $lines[$i + 2].Trim().Length -eq 0) { 3 } else { 2 }
            Write-Output ("{0}:{1} remove {2} lines" -f $path, ($i + 1), $count)
            $lines.RemoveRange($i, $count)
            $removed++
        }
    }
    $left = @($lines | Where-Object { $_ -match 'OperatingSystem\.IsWindows\(\)' })
    Write-Output ("{0}: removed={1} remaining OperatingSystem.IsWindows lines={2}" -f $path, $removed, $left.Count)
    if ($removed -eq 0) { throw "No silent return found in $path" }
    if ($PSCmdlet.ShouldProcess($path, "remove $removed silent platform returns")) {
        [System.IO.File]::WriteAllText($path, ($lines -join $newline))
    }
}

