#Requires -Version 7.0
<#
.SYNOPSIS
    Read-only: lists every OS check in C# test sources whose branch is a bare return (a silent platform
    return), with the enclosing class name and whether that class carries the Category=Integration trait.
.PARAMETER Root
    Directory to scan.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)] [string] $Root
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Write-Output "Now: $((Get-Date).ToString('s')) root=$Root"
$check = [regex]'^\s*if\s*\(\s*!?\s*OperatingSystem\s*\.\s*Is\w+\s*\(\s*\)[^)]*\)\s*(?<inline>return\s*;)?\s*$'
$count = 0
foreach ($file in Get-ChildItem -LiteralPath $Root -Recurse -File -Filter '*.cs' | Where-Object { $_.FullName -notmatch '[\\/](bin|obj)[\\/]' }) {
    $lines = @(Get-Content -LiteralPath $file.FullName)
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $m = $check.Match($lines[$i])
        if (-not $m.Success) { continue }
        $next = if ($i + 1 -lt $lines.Count) { $lines[$i + 1].Trim() } else { '' }
        $silent = $m.Groups['inline'].Success -or $next -eq 'return;'
        if (-not $silent) { continue }
        $class = '?'
        $integration = $false
        for ($j = $i; $j -ge 0; $j--) {
            if ($lines[$j] -match '\b(?:class|record)\s+(\w+)') {
                $class = $Matches[1]
                for ($k = $j - 1; $k -ge 0 -and $lines[$k].Trim() -match '^(\[|///|$)'; $k--) {
                    if ($lines[$k] -match 'Trait\(\s*"Category"\s*,\s*"Integration"') { $integration = $true }
                }
                break
            }
        }
        $count++
        Write-Output ('{0}:{1} class={2} integration={3} :: {4}' -f $file.FullName.Substring($Root.Length + 1), ($i + 1), $class, $integration, $lines[$i].Trim())
    }
}
Write-Output "Silent platform returns: $count"

