    param([string] $Root)
    $lines = [System.Collections.Generic.List[string]]::new()
    foreach ($file in Get-ChildItem -LiteralPath $Root -Recurse -File -Filter '*.trx' | Sort-Object FullName) {
        [xml]$trx = Get-Content -LiteralPath $file.FullName -Raw
        $ns = [System.Xml.XmlNamespaceManager]::new($trx.NameTable)
        $ns.AddNamespace('t', $trx.DocumentElement.NamespaceURI)
        $c = $trx.SelectSingleNode('//t:ResultSummary/t:Counters', $ns)
        $relative = [System.IO.Path]::GetRelativePath($Root, $file.FullName).Replace('\', '/')
        $lines.Add(('{0}: total={1} executed={2} passed={3} failed={4} notExecuted={5}' -f $relative, $c.GetAttribute('total'), $c.GetAttribute('executed'), $c.GetAttribute('passed'), $c.GetAttribute('failed'), $c.GetAttribute('notExecuted')))
        foreach ($r in $trx.SelectNodes('//t:UnitTestResult[@outcome!="Passed"]', $ns)) {
            $lines.Add(('  {0} {1}' -f $r.GetAttribute('outcome'), $r.GetAttribute('testName')))
        }
    }
    return $lines
}

$target = Join-Path $Worktree $Destination
Write-Output "Now: $((Get-Date).ToString('s')) destination=$target"
if ($PSCmdlet.ShouldProcess($target, 'create receipt directory')) { $null = New-Item -ItemType Directory -Path $target -Force }

foreach ($run in @($LinuxRuns -split ';' | Where-Object { $_ })) {
    $root = @((Join-Path $Worktree "TestResults/$run"), (Join-Path $RunsDir $run)) | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    if ($null -eq $root) { throw "No TRX directory for $run" }
    $summaryPath = Join-Path $target "$run.trx-summary.txt"
    if (Test-Path -LiteralPath $summaryPath) { throw "Refusing to overwrite $summaryPath" }
    $summary = @("RECEIPT $run (TRX summary of $root, written $((Get-Date).ToString('s')))") + @(Get-TrxSummaryLine -Root $root)
    $meta = Join-Path $RunsDir "$run.meta.json"
    if ($PSCmdlet.ShouldProcess($summaryPath, "write TRX summary of $run")) {
        Set-Content -LiteralPath $summaryPath -Value $summary -Encoding utf8
        Write-Output "WROTE $summaryPath lines=$($summary.Count)"
        if (Test-Path -LiteralPath $meta) {
            $metaCopy = Join-Path $target "$run.meta.json"
            Copy-Item -LiteralPath $meta -Destination $metaCopy
            $same = (Get-FileHash -LiteralPath $meta).Hash -eq (Get-FileHash -LiteralPath $metaCopy).Hash
            Write-Output "COPIED $metaCopy match=$same"
            if (-not $same) { throw "Hash mismatch for $metaCopy" }
        }
    }
}

foreach ($name in @($WindowsReceipts -split ';' | Where-Object { $_ })) {
    $source = Join-Path $RunsDir $name
    $copy = Join-Path $target $name
    if (-not (Test-Path -LiteralPath $source)) { throw "Missing $source" }
    if (Test-Path -LiteralPath $copy) { throw "Refusing to overwrite $copy" }
    if ($PSCmdlet.ShouldProcess($copy, "copy $name")) {
        Copy-Item -LiteralPath $source -Destination $copy
        $same = (Get-FileHash -LiteralPath $source).Hash -eq (Get-FileHash -LiteralPath $copy).Hash
        Write-Output "COPIED $copy match=$same original-kept=$(Test-Path -LiteralPath $source)"
        if (-not $same) { throw "Hash mismatch for $copy" }
    }
}

