#Requires -Version 7.0
<#
.SYNOPSIS
    Read-only: inventories every [Trait("Platform", ...)] in the test sources. Prints each value seen,
    the count per value, any value other than Linux or Windows, and every declaration (type or member)
    that carries more than one Platform trait, which no host lane would select.
.PARAMETER Root
    Tests root.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)] [string] $Root
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Write-Output "Now: $((Get-Date).ToString('s')) root=$Root"
$traitPattern = [regex]'\[\s*(?:Xunit\.)?Trait\s*\(\s*"Platform"\s*,\s*"(?<value>[^"]*)"\s*\)\s*\]'
$counts = @{}
$multi = 0
foreach ($file in Get-ChildItem -LiteralPath $Root -Recurse -File -Filter '*.cs' | Where-Object { $_.FullName -notmatch '[\\/](bin|obj)[\\/]' }) {
    $lines = Get-Content -LiteralPath $file.FullName
    $pending = [System.Collections.Generic.List[string]]::new()
    $pendingStart = 0
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        $found = $traitPattern.Matches($line)
        foreach ($m in $found) {
            $value = $m.Groups['value'].Value
            if (-not $counts.ContainsKey($value)) { $counts[$value] = 0 }
            $counts[$value]++
            if ($pending.Count -eq 0) { $pendingStart = $i + 1 }
            $pending.Add($value)
        }
        $trimmed = $line.Trim()
        # An attribute block ends at the first line that is neither blank, a comment, nor an attribute.
        $isAttributeOrTrivia = $trimmed -eq '' -or $trimmed.StartsWith('[') -or $trimmed.StartsWith('//')
        if (-not $isAttributeOrTrivia) {
            if ($pending.Count -gt 1) {
                $multi++
                Write-Output ('MULTI {0}:{1} values={2} decl={3}' -f $file.FullName.Substring($Root.Length + 1), $pendingStart, ($pending -join ','), $trimmed)
            }
            $pending.Clear()
        }
    }
}
foreach ($key in $counts.Keys | Sort-Object) {
    $flag = if ($key -in @('Linux', 'Windows')) { '' } else { ' UNEXPECTED-VALUE' }
    Write-Output ('VALUE {0} count={1}{2}' -f $key, $counts[$key], $flag)
}
Write-Output "Declarations with more than one Platform trait: $multi"

#Requires -Version 7.0
<#
.SYNOPSIS
    Read-only: lists every use case through the plugin (client.UseCases.ListAsync), reads each one
    (client.UseCases.GetAsync) and prints every FR link whose FR id is one of the named ids, plus the
    coverage DTO's counts (client.UseCases.GetCoverageAsync).
.PARAMETER FrIds
    Semicolon-separated FR ids to look for.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)] [string] $FrIds
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'CcPlugin.ps1')

$wanted = @($FrIds -split ';' | Where-Object { $_ })
Write-Output "Now: $((Get-Date).ToString('s')) looking for: $($wanted -join ', ')"

$list = Invoke-CcPlugin -Method 'client.UseCases.ListAsync' -Params ([ordered]@{})
$listResult = Get-CcValue (Get-CcValue $list.Parsed 'payload') 'result'
if ($null -eq $listResult) { Write-Output "LIST exit=$($list.ExitCode)"; Write-Output $list.Raw; exit 1 }
$items = @(Get-CcValue $listResult 'items')
if ($items.Count -eq 0 -and $listResult -is [System.Collections.IList]) { $items = @($listResult) }
Write-Output "LIST exit=$($list.ExitCode) useCases=$($items.Count)"

$hits = 0
foreach ($summary in $items) {
    $id = Get-CcValue $summary 'id'
    if ($null -eq $id) { $id = Get-CcValue $summary 'useCaseId' }
    $detail = Invoke-CcPlugin -Method 'client.UseCases.GetAsync' -Params ([ordered]@{ useCaseId = $id })
    $result = Get-CcValue (Get-CcValue $detail.Parsed 'payload') 'result'
    if ($null -eq $result) { Write-Output "GET $id exit=$($detail.ExitCode) (no result)"; continue }
    foreach ($link in @(Get-CcValue $result 'frLinks')) {
        $frId = [string](Get-CcValue $link 'frId')
        if ($frId -in $wanted) {
            $hits++
            Write-Output ('LINK useCase={0} title={1} frId={2} linkType={3}' -f $id, (Get-CcValue $result 'title'), $frId, (Get-CcValue $link 'linkType'))
        }
    }
}
Write-Output "Links to the named FRs: $hits"

$coverage = Invoke-CcPlugin -Method 'client.UseCases.GetCoverageAsync' -Params ([ordered]@{})
$cov = Get-CcValue (Get-CcValue $coverage.Parsed 'payload') 'result'
if ($null -ne $cov) {
    Write-Output ('COVERAGE totalUseCases={0} totalFunctionalRequirements={1} linkedUseCases={2} linkedFunctionalRequirements={3}' -f (Get-CcValue $cov 'totalUseCases'), (Get-CcValue $cov 'totalFunctionalRequirements'), (Get-CcValue $cov 'linkedUseCases'), (Get-CcValue $cov 'linkedFunctionalRequirements'))
    $missing = @(Get-CcValue $cov 'functionalRequirementsWithoutRealizesUseCase')
    foreach ($frId in $wanted) { Write-Output "COVERAGE lists $frId without a Realizes use case: $($missing -contains $frId)" }
}
else { Write-Output "COVERAGE exit=$($coverage.ExitCode) (no result)" }

Input.old_string:
if ($null -eq $listResult) { Write-Output "LIST exit=$($list.ExitCode)"; Write-Output $list.Raw; exit 1 }
$items = @(Get-CcValue $listResult 'items')
if ($items.Count -eq 0 -and $listResult -is [System.Collections.IList]) { $items = @($listResult) }

Input.new_string:
# An empty result list unrolls to null through Get-CcValue, so an explicit empty list in the raw reply means zero use cases.
$emptyList = $list.ExitCode -eq 0 -and $list.Raw -match '(?m)^\s*result:\s*\[\]\s*$'
if ($null -eq $listResult -and -not $emptyList) { Write-Output "LIST exit=$($list.ExitCode)"; Write-Output $list.Raw; exit 1 }
$items = @()
if ($null -ne $listResult) {
    $items = @(Get-CcValue $listResult 'items')
    if ($items.Count -eq 0 -and $listResult -is [System.Collections.IList]) { $items = @($listResult) }
}

