# Read-only remote probe (runs on PAYTON-LEGION2 as lab-wsman): reports whether the interactive lane
# worktree and its TestResults exist, its HEAD, and a TRX summary (counts and every non-passed case).
$ErrorActionPreference = 'Stop'
$env:GIT_CONFIG_COUNT = '1'
$env:GIT_CONFIG_KEY_0 = 'safe.directory'
$env:GIT_CONFIG_VALUE_0 = '*'
$wt = 'F:/GitHub/McpServer/.worktrees/unit-green-interactive-20261019'
$runRoot = Join-Path $wt 'TestResults/unit-green-win-interactive-20261019'
"PROBE $((Get-Date).ToString('s')) host=$env:COMPUTERNAME user=$env:USERNAME"
"WORKTREE exists=$(Test-Path -LiteralPath $wt)"
if (Test-Path -LiteralPath $wt) {
    try { "HEAD $((git -C $wt rev-parse HEAD 2>&1) -join ' ')" } catch { "HEAD unreadable: $($_.Exception.Message)" }
    $item = Get-Item -LiteralPath $wt
    "WORKTREE created=$($item.CreationTime.ToString('s')) owner=$((Get-Acl -LiteralPath $wt).Owner)"
}
"TESTRESULTS exists=$(Test-Path -LiteralPath $runRoot)"
if (Test-Path -LiteralPath $runRoot) {
    foreach ($trx in Get-ChildItem -LiteralPath $runRoot -Recurse -Filter '*.trx' | Sort-Object FullName) {
        if ($trx.Length -eq 0) { "TRX $($trx.FullName.Substring($runRoot.Length)) EMPTY"; continue }
        try {
            [xml]$doc = Get-Content -LiteralPath $trx.FullName -Raw
            $nsm = [System.Xml.XmlNamespaceManager]::new($doc.NameTable)
            $nsm.AddNamespace('t', $doc.DocumentElement.NamespaceURI)
            $c = $doc.SelectSingleNode('//t:ResultSummary/t:Counters', $nsm)
            $times = $doc.SelectSingleNode('//t:Times', $nsm)
            "TRX $($trx.FullName.Substring($runRoot.Length)) written=$($trx.LastWriteTime.ToString('s')) start=$($times.GetAttribute('start')) total=$($c.GetAttribute('total')) executed=$($c.GetAttribute('executed')) passed=$($c.GetAttribute('passed')) failed=$($c.GetAttribute('failed')) notExecuted=$($c.GetAttribute('notExecuted'))"
            foreach ($r in $doc.SelectNodes('//t:UnitTestResult[@outcome!="Passed"]', $nsm)) {
                $m = $r.SelectSingleNode('t:Output/t:ErrorInfo/t:Message', $nsm)
                $msg = if ($null -ne $m) { ($m.InnerText -replace '\s+', ' ').Trim() } else { '' }
                if ($msg.Length -gt 400) { $msg = $msg.Substring(0, 400) }
                "  $($r.GetAttribute('outcome')) $($r.GetAttribute('testName')) :: $msg"
            }
        }
        catch { "TRX $($trx.FullName) unreadable: $($_.Exception.Message)" }
    }
}
"END $((Get-Date).ToString('s'))"

